                      ShowMoveRight="true"
                      OnMoveLeft="@(task => MoveTask(task, StatusToDo))"
                      OnMoveRight="@(task => MoveTask(task, StatusDone))"
                      OnAddTask="@(newTask => AddTask(newTask, StatusInProgress))" />

        <KanbanColumn ColumnName="@StatusDone"
                      Tasks="@GetFilteredTasks(StatusDone)"
                      ShowMoveLeft="true"
                      ShowMoveRight="false"
                      OnMoveLeft="@(task => MoveTask(task, StatusInProgress))"
                      OnAddTask="@(newTask => AddTask(newTask, StatusDone))" />
    </div>
}

